"use strict";(globalThis.webpackChunksanctuary_amongst_the_starts=globalThis.webpackChunksanctuary_amongst_the_starts||[]).push([[6833],{9147(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>s,metadata:()=>a,toc:()=>h});const a=JSON.parse('{"id":"world-information/locations/inner-system/earth-and-earth-orbit","title":"Earth & Earth Orbit","description":"---","source":"@site/docs/world-information/locations/inner-system/earth-and-earth-orbit.md","sourceDirName":"world-information/locations/inner-system","slug":"/world-information/locations/inner-system/earth-and-earth-orbit","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/inner-system/earth-and-earth-orbit","draft":false,"unlisted":false,"editUrl":"https://github.com/kaelynj/sanctuary-amongst-the-stars/docs/world-information/locations/inner-system/earth-and-earth-orbit.md","tags":[],"version":"current","frontMatter":{},"sidebar":"loreSidebar","previous":{"title":"World Information","permalink":"/sanctuary-amongst-the-stars/docs/world-information/"},"next":{"title":"Inner System Fringe","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/inner-system/inner-system-fringe"}}');var r=n(4848),i=n(8453);const s={},o="Earth & Earth Orbit",l={},h=[{value:"Earth Orbit",id:"earth-orbit",level:2},{value:"The Fence",id:"the-fence",level:2},{value:"The junkyard",id:"the-junkyard",level:2},{value:"Orbital Settlements",id:"orbital-settlements",level:2},{value:"Fresh Kills",id:"fresh-kills",level:3},{value:"Hexagon",id:"hexagon",level:3},{value:"Paradise",id:"paradise",level:3},{value:"Remembrance",id:"remembrance",level:3},{value:"Vo Nguyen",id:"vo-nguyen",level:3},{value:"Earth",id:"earth",level:2},{value:"Getting to Earth",id:"getting-to-earth",level:3},{value:"Exploring Earth",id:"exploring-earth",level:3},{value:"Residents",id:"residents",level:3}];function d(e){const t={em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.header,{children:(0,r.jsx)(t.h1,{id:"earth--earth-orbit",children:"Earth & Earth Orbit"})}),"\n",(0,r.jsx)(t.hr,{}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"Posted by:"})," ",(0,r.jsx)(t.em,{children:"Eludere"})]}),"\n",(0,r.jsx)(t.p,{children:"The former shining beacon of transhumanity is now the grungy, dangerous ghetto where you wonder how things deteriorated so badly and fear for your safety."}),"\n",(0,r.jsx)(t.h2,{id:"earth-orbit",children:"Earth Orbit"}),"\n",(0,r.jsx)(t.p,{children:"During the Fall, infugees flooded any habitat or satellite willing to accept their transfer. Refugees fled on anything that could be sealed tight and strapped to a rocket. Dozens of emergency habitats were constructed or inflated, and many are still in use."}),"\n",(0,r.jsx)(t.p,{children:"Roughly three million still live in Earth's orbit, surviving in the shadow of transhumanity's abandoned home. Many cling to old-Earth identities out of sheer stubborn cussedness. Bioconservative and reclaimer memes are common, as are old-Earth rivalries, so visitors would be wise to study their history before trying to blend in. While infomorphs and synthmorphs are the most common morphs in orbit, they still face challenges including economic hardship, quarantine, indentured servitude, and discrimination."}),"\n",(0,r.jsx)(t.p,{children:"There are hundreds of small habitats in orbit, some with residents and some long abandoned. Tin-can stations, clusters, toruses, and cylinders are all common."}),"\n",(0,r.jsx)(t.h2,{id:"the-fence",children:"The Fence"}),"\n",(0,r.jsx)(t.p,{children:"With the TITANs an every-present risk of escaping the planet, someone had to make an effort to keep them bottled up where they couldn't harm the survivors. That's what the Fence is for. No one has claimed responsibility for setting up the blockade, but the assumption is that the Consortium supports and maintains it."}),"\n",(0,r.jsx)(t.p,{children:"Over two-thousand satellites in low Earth orbit, ranging in size from sensor platforms to micro- and nano-satellites, monitor and take down anything coming into or trying to leave the kill zone (300-350 kilometers altitude). Signal jammers hose digital communications. Smart mines lurk, ready to swarm anything that moves, while hunter-killer drones catch anything that slips past. The Fence is equipped with almost every weapon imaginable: lasers, railguns, antimatter missiles -- even old-fashioned nukes."}),"\n",(0,r.jsx)(t.h2,{id:"the-junkyard",children:"The junkyard"}),"\n",(0,r.jsx)(t.p,{children:"Leftover rockets, screws, screwdrivers, boosters, and other junk form a thick ring around the planet called the Junkyard. The drifting scrap is a dumping ground for the locals; the debris is either safely burned up in atmosphere or more likely destroyed by the weapons platforms surrounding the planet."}),"\n",(0,r.jsx)(t.p,{children:"Pre-Fall and post-Fall parts can be found in the Junkyard, ready to be pried out of discarded ships and sold. More exotic finds can be salvaged, including the remains of refugees, experimental technology, or Earth relics lost during the Fall."}),"\n",(0,r.jsx)(t.h2,{id:"orbital-settlements",children:"Orbital Settlements"}),"\n",(0,r.jsx)(t.h3,{id:"fresh-kills",children:"Fresh Kills"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Habitat Type/Orbit:"})," Cluster/Earth-Luna L5"]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Allegiance:"})," Scum"]}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:'Generously calling itself a "reclamation center," Fresh Kills is owned and operated by Sugali Ali. Several thousand residents follow the direction of their four-armed "Pirate King" to provide a semi-secure base for salvage work in orbit. Don\'t ravel alone on this habitat. Tensions with nearby Hexagon make ships approach cautiously to avoid startling either well-armed habitat into aggression.'}),"\n",(0,r.jsx)(t.h3,{id:"hexagon",children:"Hexagon"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Habitat Type/Orbit:"})," Modified Torus/Earth-Luna L5"]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Allegiance:"})," Planetary Consortium (Direct Action)"]}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"This fortress uneasily shares the Earth-Luna L5 point with Fresh Kills. Direct Action's weapons-testing and training facilities reside on Hexagon and the company develops most of the Consortium's latest military advances here. In addition to combat morphs and weapon engineers, the habitat boasts one of the most impressive sensor systems in the inner system, mostly pointed at all times towards Earth and its sealed-away dangers."}),"\n",(0,r.jsx)(t.h3,{id:"paradise",children:"Paradise"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Habitat Type/Orbit:"})," Torus/Earth-Sun L1"]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Allegiance:"})," Planetary Consortium"]}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"Once a sun-drenched resort for the rich trendsetters of Earth, Paradise was overwhelmed with refugees during the Fall, leading to the habitat losing most of its shine and glitter to semi-permanent emergency camps. Recently Paradise has regained some of the old reputation, at the rumored cost of forcible relocation of less-fortunate residents. Increases in security have led to more rumors that Paradise is the secret face-to-face meeting round for the hypercorp Council for matters requiring more secure communication."}),"\n",(0,r.jsx)(t.h3,{id:"remembrance",children:"Remembrance"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Habitat Type/Orbit:"})," O'Neill Cylinder/Earth-Luna L4"]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Allegiance:"})," Lunar-Lagrange Alliance"]}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"The largest station near Earth, Remembrance is capital to the Lunar-Lagrange Alliance. Two thirty-five-kilometer counter-rotating cylinders provide living and working space for over two million residents. One cylinder is overcrowded and barely functioning, while the other provides healthy living for Remembrance elites and LLA officials. Remembrance is led by Mayor Nandi Setsin, a passionate reclaimer known for her abrasive leadership style and slick ability to avoid corruption convictions. Her rocky partnership with LLA President Avra Don has proven beneficial to them both."}),"\n",(0,r.jsx)(t.h3,{id:"vo-nguyen",children:"Vo Nguyen"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Habitat Type/Orbit:"})," O'Neill Cylinder/GEO orbit"]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Allegiance:"})," Lunar-Lagrange Alliance"]}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"Led by Tate Markess, the Executive Director of the Earth Reclamation Project and spokesperson for the reclaimer movement, Vo Nguyen is a reclaimer stronghold and launching point for reclaimer activism and missions to Earth. Disagreements over mission approaches pit tech-savvy reclaimers against neo-primitivist. The station is secured against outside threats behind a cloud of space debris and killsats, but internal conflicts may get them all killed anyway if violence escalates."}),"\n",(0,r.jsx)(t.h2,{id:"earth",children:"Earth"}),"\n",(0,r.jsx)(t.p,{children:"Major cities across the globe were wiped clean during the Fall by nukes, orbital strikes, and antimatter weapons. Some craters and scars are even visible from orbit, such as the glassy patch that used to be Chicago. Mass drivers scattered pockmarks across the planet, following the path of TITAN advances and factories. Mid-Fall, the Pacific space elevator came down, snaking across eastern Asia and leaving a deep gorge in its wake across the continent. Nuclear winter has left Europe buried under snowdrifts and glaciers, while Africa is a parched landscape of deserts and firestorms. Massive nanoswarm clouds create weird local weather distortions from hail to tornadoes. Ash clouds still linger, coating the landscape."}),"\n",(0,r.jsx)(t.h3,{id:"getting-to-earth",children:"Getting to Earth"}),"\n",(0,r.jsx)(t.p,{children:"The Junkyard provides good cover for approaching the Fence, but just making a run for it is a good way to get splattered. The smarter way is to map the fence for areas where mines haven't regenerated or where a large patch of de-orbiting debris can provide cover from sensors. Drones carrying nanofabbers and neutrino transceivers can slip into these gaps, with the intent of printing out a morph you can egocast into. Small, heavily shielded ships have a chance if they coast on momentum to avoid attention. Other options include a distraction to occupy killsats or camouflaging your ship/bot as one of the Fence's own service drones."}),"\n",(0,r.jsx)(t.p,{children:"The Kilimanjaro space elevator is still in place though powered down, if a team has the fortitude to reopen that tomb. Lunar mass drivers are still programmed to rain death from orbit at any possible sites of TITAN activity. Their payloads always make it to the surface, so hitching a ride is feasible, but the landing is rough and may be in the center of TITAN activity."}),"\n",(0,r.jsx)(t.p,{children:"Getting back off the planet is more difficult. For that, egocasting is recommended, but if physical transport is required, there are scavengers and reclaimers that make irregular runs to the surface that can be convinced to help out."}),"\n",(0,r.jsx)(t.h3,{id:"exploring-earth",children:"Exploring Earth"}),"\n",(0,r.jsx)(t.p,{children:"The discarded trappings of transhumanity can be found at every turn, abandoned in haste. Half-burnt cities, roads reclaimed by plant life, freeways packed with fleeing vehicles that never made it. Everywhere you find the skeletons and flash-burned outlines of the dead. Everything on the planet suffered in the wake of TITAN machines and nuclear attacks, so most animal life is absent too."}),"\n",(0,r.jsx)(t.p,{children:"Treasures may be found in the ruins, but explorers must be alert for environmental dangers. Sinkholes and collapsing infrastructure are common, and getting around a city involves as much climbing and rappelling as it does walking. While most sites hit by nuclear weapons have cooled enough for fallout to be negligible, check to be sure. And without the protection of an ozone layer, clear skies risk sunburn within minutes of exposure."}),"\n",(0,r.jsx)(t.h3,{id:"residents",children:"Residents"}),"\n",(0,r.jsx)(t.p,{children:"Stalking through the ruins are other dangers. TITAN war machines still lurk, following their encoded directions to stalk new victims. Headhunters and fractals remain passive until new targets are detected. Nanoswarms resembling fog banks roam aimlessly for organic matter to flank and dissolve."}),"\n",(0,r.jsx)(t.p,{children:"There are thousands of exsurgents left behind as well. The victims of genetic and viral manipulation, bodies, minds, or both are warped far from being recognizable as transhuman. Many remain at sites of old TITAN activity, continuing the tasks they were set to when the TITANs left. Entire cities of TITAN puppets -- transhumans with hacked and subverted minds -- go about their business, or pretend to be survivors to lure in the unwary."}),"\n",(0,r.jsx)(t.p,{children:"If TITAN machines and exsurgents have survived the changes of Earth's surface, so have the scrappiest representatives of transhumanity. Close observation can detect pockets of heat and infrared radiation that don't match known TITAN sources. These spots of hope are tucked into the Ozark caves and abandoned mine shafts of southern Appalachia, the highlands a Papua and New Guinea, peeping past the trees of Vietnam and Laos, the caves of the Swiss Alps, warm spots underwater near where the Philippines used to be, and off the coast of Madagascar. Some of these may be bait to lure victims, but others may be signs of surviving transhumanity. And, of course, many survivors remain frozen in cryogenic facilities or stored away in digital form, awaiting rescue and revival."})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>o});var a=n(6540);const r={},i=a.createContext(r);function s(e){const t=a.useContext(i);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);